def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    quoted = False

    def end_field():
        if quoted:
            fields.append(''.join(field))
        else:
            fields.append(''.join(field).strip())

    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
                quoted = True
            else:
                field.append(c)
        elif quoted:
            if c == ',':
                end_field()
                field = []
                quoted = False
        elif c == '"' and not field:
            in_quotes = True
        elif c == ',':
            end_field()
            field = []
        else:
            field.append(c)
        i += 1

    end_field()
    return fields
